<section class="section-space"><div class="page-shell max-w-4xl"><div class="max-w-2xl"><p class="eyebrow"><i class="ph ph-question" aria-hidden="true"></i><span>Help and answers</span></p><h1 class="section-title mt-4">Frequently asked questions</h1><p class="section-copy">Clear answers about accounts, registrations, tickets, and events.</p></div><?php if ($faqs === []): ?><div class="event-empty-state mt-10"><span><i class="ph ph-question" aria-hidden="true"></i></span><h2>No answers published yet</h2><p>Contact the OEMS team if you need help now.</p></div><?php else: ?><div class="mt-10 grid gap-3"><?php foreach ($faqs as $faq): ?><details class="dashboard-panel group"><summary class="flex min-h-11 cursor-pointer list-none items-center justify-between gap-4 font-bold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)]"><span><?= e($faq['question']) ?></span><i class="ph ph-plus" aria-hidden="true"></i></summary><div class="mt-4 space-y-4 border-t border-[var(--line)] pt-4 text-[var(--ink-muted)]"><?php foreach (preg_split('/\n\s*\n/', trim((string) $faq['answer'])) ?: [] as $paragraph): ?><p><?= nl2br(e(trim($paragraph)), false) ?></p><?php endforeach; ?></div></details><?php endforeach; ?></div><?php endif; ?></div></section>
